    static RetailText()
    {
        foreach (var (language, values) in Translations)
            if (values.Length != SourceKeys.Length || values.Any(string.IsNullOrWhiteSpace))
                throw new InvalidOperationException($"Invalid retail translations for {language}.");
    }

    internal static IReadOnlyCollection<string> SupportedLanguages => Translations.Keys;
    internal static IReadOnlyList<string> Keys => Array.AsReadOnly(SourceKeys);

    internal static string Get(string key)
    {
        var index = Array.IndexOf(SourceKeys, key);
        if (index < 0) return key;
        return Translations.TryGetValue(Localization.CurrentLanguage, out var values)
            ? values[index]
            : Translations["en"][index];
    }
}
